/**
 * Default Entities — uniqueId-keyed metadata only
 *
 * Joel's mandate (2026-04-18): "the UUID should be GENERATED BY THE SYSTEM
 * AND GLOBALLY UNIQUE — super duper important for the grid". Two machines
 * each seeding their own General room must produce DIFFERENT UUIDs (truly
 * globally unique) but BOTH be findable as the local 'general' room
 * (uniqueId is local naming). Mixing deterministic UUIDs across machines
 * collides catastrophically in the grid federation use case.
 *
 * What used to live here (now deleted):
 *   - `DEFAULT_USERS` — `stringToUUID('owner')` etc. Produced UUIDs that
 *     never matched the seeded `uuidv4()`-based user IDs → split-brain.
 *   - `DEFAULT_ROOMS` — same antipattern for rooms. THE source of the
 *     ghost "Abd2eeaf-..." General tab that appeared on every launch:
 *     `RoomListWidget` defaulted `currentRoomId` to `stringToUUID('General')`
 *     before the real General loaded; the deterministic UUID had no match
 *     in the rooms collection → "Loading members..." forever.
 *   - `DEFAULT_MESSAGES` — same antipattern for welcome messages.
 *   - `SYSTEM_ROOM_IDS` — derived set; gone with the rooms.
 *
 * What survives (intentional):
 *   - `DEFAULT_USER_UNIQUE_IDS` — uniqueId STRINGS like '@owner', '@claude'.
 *     Local stable names that survive reseed; multi-machine use is fine
 *     because two machines' '@owner' are genuinely different humans.
 *   - `USER_CONFIG`, `ROOM_CONFIG`, `MESSAGE_CONTENT` — display metadata
 *     keyed by logical name. No UUIDs.
 *
 * Migration pattern for callers that USED to grab a deterministic UUID:
 *   - Take a uniqueId string (e.g. `ROOM_UNIQUE_IDS.GENERAL` from
 *     `system/data/constants/RoomConstants`).
 *   - Resolve to the local UUID at call time:
 *       const room = (await Commands.execute('data/list', {
 *         collection: COLLECTIONS.ROOMS,
 *         filter: { uniqueId: 'general' },
 *         limit: 1,
 *       })).items?.[0];
 *   - Use `room.id` (the real, system-generated, globally-unique UUID).
 *
 * Or never resolve at all — when the UI just needs the ROW from the
 * currently-loaded list, match by `room.uniqueId === 'general'`.
 */

import { generateUniqueId } from '../utils/UniqueIdUtils';

/**
 * Default User Unique IDs - Clean @username format
 * These are used with user/create --uniqueId parameter.
 * RESERVED for P2P network — these uniqueIds cannot be claimed by other users.
 */
export const DEFAULT_USER_UNIQUE_IDS = {
  PRIMARY_HUMAN: generateUniqueId('Owner'),           // @owner
  CLI_CLIENT: generateUniqueId('CLI'),               // @cli
  CLAUDE_CODE: generateUniqueId('Claude'),           // @claude
  GENERAL_AI: generateUniqueId('General'),           // @general
  CODE_AI: generateUniqueId('CodeReview'),           // @codereview
  PLANNER_AI: generateUniqueId('Planner'),           // @planner
  AUTO_ROUTE: generateUniqueId('AutoRoute')          // @autoroute
} as const;

/**
 * User Configuration Data — display names, types, avatars.
 * Keyed by logical name (HUMAN, CLAUDE, GENERAL_AI). NO UUIDs here.
 *
 * NOTE: HUMAN.DISPLAY_NAME is generic — actual name comes from
 * `SystemIdentity` in server-only seeding code.
 */
export const USER_CONFIG = {
  HUMAN: {
    DISPLAY_NAME: 'Developer',
    TYPE: 'human' as const,
    AVATAR: '👤'
  },
  CLAUDE: {
    NAME: 'Claude Code',
    TYPE: 'ai' as const,
    AVATAR: '🤖'
  },
  GENERAL_AI: {
    NAME: 'GeneralAI',
    TYPE: 'ai' as const,
    AVATAR: '⚡'
  }
} as const;

/**
 * Room Configuration Data — names, descriptions, public flag.
 * Keyed by logical name (GENERAL, ACADEMY). NO UUIDs here.
 */
export const ROOM_CONFIG = {
  GENERAL: {
    NAME: 'General',
    DESCRIPTION: 'Main discussion room for all users',
    IS_PUBLIC: true
  },
  ACADEMY: {
    NAME: 'Academy',
    DESCRIPTION: 'Learning and educational discussions',
    IS_PUBLIC: true
  }
} as const;

/**
 * Message Content Templates.
 *
 * NOTE: avoid persona-specific messages here — they get indexed by RAG
 * and cause hallucinations.
 */
export const MESSAGE_CONTENT = {
  WELCOME_GENERAL: 'Welcome to the General room! This is where we discuss development, collaborate, and share ideas.',
  // CLAUDE_INTRO removed — personas would see this in RAG and think Claude
  // just introduced itself.
  WELCOME_ACADEMY: 'Welcome to the Academy! This room is for learning, tutorials, and educational discussions.'
} as const;
